{"views":[{"label":"表格视图","type":"grid_2n5umv6"}],"title":"未关闭的问题","uniqueFieldType":"varchar","uniqueType":"varchar","print_id":null,"form_rights":{},"form_key":"","script":"Object.assign({
 // 根据周报状态控制操作列
 applyReadOnly: function (form, reportComp) {
 if (!form || !reportComp) return

 const main = reportComp.main || {}
 const appointment = reportComp.appointment || {}
 const appointmentInfo = appointment.info || {}

 const weeklyReportId = main.weeklyReportId
 const isDraft = appointmentInfo.isDraft
 const isEditState = reportComp.isEditState

 // 有周报ID + 非草稿 + 当前不是编辑状态 => 只读
 const readOnly = !!(
 weeklyReportId &&
 !isDraft &&
 isEditState === false
 )

 const applyOperationColumn = function () {
 if (!form.listConfig) return

 /*
 * 首次执行时缓存操作列配置。
 * 不能每次都缓存，否则隐藏后会把 null 缓存下来，
 * 后面将无法恢复。
 */
 if (!form.__operationColumnCached) {
 form.__operationColumnCached = true
 form.__operationRowHandle = form.listConfig.rowHandle || null
 }

 if (readOnly) {
 // 只读：隐藏操作列
 if (typeof form.$set === 'function') {
 form.$set(form.listConfig, 'rowHandle', null)
 } else {
 form.listConfig.rowHandle = null
 }
 } else {
 // 可编辑：恢复操作列
 if (typeof form.$set === 'function') {
 form.$set(
 form.listConfig,
 'rowHandle',
 form.__operationRowHandle
 )
 } else {
 form.listConfig.rowHandle = form.__operationRowHandle
 }
 }

 console.log(
 'readOnly=',
 readOnly,
 'rowHandle=',
 form.listConfig.rowHandle
 )
 }

 applyOperationColumn()

 // 兼容列表配置稍晚完成初始化的情况
 if (typeof form.$nextTick === 'function') {
 form.$nextTick(applyOperationColumn)
 }
 },

 onLoad: function (form) {
 let cur = form
 let reportComp = null

 // 向上查找周报组件
 while (cur) {
 if (
 cur.$options &&
 (
 cur.$options.name === 'report' ||
 cur.$options.name === 'WeeklyReport'
 )
 ) {
 reportComp = cur
 break
 }

 if (
 cur.main &&
 cur.appointment &&
 typeof cur.isSubmmitted === 'function'
 ) {
 reportComp = cur
 break
 }

 cur = cur.$parent
 }

 if (!reportComp) {
 console.warn('未找到周报组件，无法控制操作列')
 return
 }

 const vm = this

 // 避免 onLoad 重复执行时重复注册监听器
 if (typeof form.__unwatchOperationColumn === 'function') {
 form.__unwatchOperationColumn()
 }

 // 首次加载立即设置操作列状态
 vm.applyReadOnly(form, reportComp)

 // 周报状态变化时动态显示或隐藏操作列
 form.__unwatchOperationColumn = reportComp.$watch(
 function () {
 return [
 reportComp.isEditState,
 reportComp.appointment &&
 reportComp.appointment.info &&
 reportComp.appointment.info.isDraft,
 reportComp.main &&
 reportComp.main.weeklyReportId
 ]
 },
 function () {
 vm.applyReadOnly(form, reportComp)
 }
 )
 },


 // ========== 按钮前置事件 ==========
 // 参数说明：
 // template —— 当前数据模板实例（动态表单里的"数据模板"组件）
 // action —— 触发按钮的标识（这里我们只处理 'shuaxin' 刷新）
 // position —— 按钮位置
 // selection —— 当前选中行数据
 // data —— 表单/模板数据
 // callback —— 回调函数：callback(true) 放行默认动作；callback(false) 阻止
 beforeSubmit: function(template, action, position, selection, data, callback) {
 if (action === 'shuaxin') {
 // ---------------------------------------------------------------
 // 1. 沿 $parent 向上查找 report/index.vue 组件实例（组件名 'report'）
 // 目的是拿到它的两个计算属性：componentKey、indexKey
 // ---------------------------------------------------------------
 const ReportTypeEnum = {
 WeeklyReport: 'Weekly',
 BiweeklyReport: 'Biweekly',
 HalfMonthlyReport: 'HalfMonthly',
 MonthlyReport: 'Monthly',
 QuarterlyReport: 'Quarterly',
 PhaseReport: 'Phase'
 }
 let cur = template
 let reportComp = null
 while (cur) {
 if (cur.$options && cur.$options.name === 'Report') {
 reportComp = cur
 break
 }
 cur = cur.$parent
 }

 // 直接读取 report 组件上的 computed，实时反映当前选中项
 const componentKey = reportComp ? reportComp.componentKey : ''
 const indexKey = reportComp ? reportComp.indexKey : 0
 const projectId = reportComp ? reportComp.reportProjectId : ''
 console.log(reportComp,'reportCompreportComp')
 console.log('componentKey=', componentKey, 'indexKey=', indexKey,'projectId=',projectId)
 // if(reportComp){
 // reportComp.filter.loading = true
 // }
 // ---------------------------------------------------------------
 // 2. 继续向上查找"当前数据模板所在的外层动态表单"
 // 动态表单会提供 getFormData / setFieldData 方法
 // ---------------------------------------------------------------
 let current = template
 let form = null

 while (current) {
 // 当前节点本身就是动态表单
 if (
 typeof current.getFormData === 'function' &&
 typeof current.setFieldData === 'function'
 ) {
 form = current
 break
 }

 // 当前节点持有 dynamicForm 属性，且它才是真正的动态表单
 if (
 current.dynamicForm &&
 typeof current.dynamicForm.getFormData === 'function' &&
 typeof current.dynamicForm.setFieldData === 'function'
 ) {
 form = current.dynamicForm
 break
 }

 current = current.$parent
 }

 // ---------------------------------------------------------------
 // 3. 从模板参数里取 weeklyReportId / year
 // dp —— 动态参数(dynamicParams)；fp —— 普通参数(params)
 // 优先 dynamicParams，其次 params，最后 params.params
 // ---------------------------------------------------------------
 let dp = template.dynamicParams || {}
 let fp = template.params || {}
 let fpParams = fp.params || {}
 let weeklyReportId = dp.weeklyReportId || fp.weeklyReportId || fpParams.weeklyReportId
 let year = dp.year || fp.year || fpParams.year
 console.log('weeklyReportId=', weeklyReportId, 'year=', year)
 console.log(weeklyReportId, year)
 console.log(template, '打印template') // 打印整个 template 实例，方便排查字段

 // ---------------------------------------------------------------
 // 4. 调用刷新接口（只刷新当前这张周报表）
 // 注意：下面注释掉的代码块是"刷新后回填字段 / 子表重新查询"的示例，
 // 供你后续按需打开使用，这里先保留不删。
 // ---------------------------------------------------------------
 this.$request({
 url: '/pp-project/v3/api/projectReport/refresh',
 method: 'post',
 data: {
 projectId,
 year: year,
 refreshType: 'Issue',
 reportType: ReportTypeEnum[componentKey],
 index: indexKey
 } 
 }).then(res => {
 //const child = reportComp && reportComp.$refs ? reportComp.$refs.childRef : null
 //if (child && typeof child.existWeeklyReport === 'function') {
 // child.existWeeklyReport()
 // }
 if(res.state === 200) {
 const fields = Object.keys(form.formData)
 const fieldEditList = []
 fields.forEach(item=>{
 let getData = form.getFormRights(item)
 if(getData?.read) {
 fieldEditList.push(item)
 }
 })
 console.log(fieldEditList,'fieldEditList1122')
 if(fieldEditList.length) {
 fieldEditList.forEach(fieldItem=>{
 form.setFieldData(fieldItem, res.data[fieldItem]) 
 })
 }
 // 测试数据
 // 获取 title 字段值
 // const oldTitle = formData.title
 // 给 title 字段赋值
 // form.setFieldData("phase", '123') 
 // 子表刷新
 if (typeof template.search === 'function') {
 template.$message({ message: "刷新成功", type: "success" });
 template.search()
 } 
 }else {
 template.loading = false
 } 
 })
 .finally(() => {
 template.loading = false
 //reportComp.filter.loading = false
 })
 // 只刷新，不走默认按钮动作（需要拦截时取消下面注释）
 // callback(false)
 // return
 }
 // 其它按钮一律放行
 callback(true)
 },

 // ========== 按钮后置事件（提交完成后回调） ==========
 // 这里什么都不做，直接放行
 afterSubmit: function(template, action, position, selection, data, callback) {
 callback(true)
 }
